(142, 'LH2026050001', 'pending', NULL, NULL, NULL, '2026', '85000', 'Iliyasu Idris', '01026033218', 'March', 'Cyber Security and Networking', 'Computer science', 'male', '2004-07-18', '07062204899', 'iliyasuidris403@gmail.com', 'Emir palace Dukku', 'Nigerian', 'Gombe', 'Dukku', 'Babangida Idi', 'father', '09032452386', NULL, 'Federal low cost makama new extension,Bauchi state.', 'Civil servant', 'Civil Service commission', 'Babangida Idi', '09032452386', NULL, 'Federal low cost makama new extension,Bauchi state.', NULL, NULL, NULL, NULL, 'AA', 'Halal foods', 'non-smoker', NULL, NULL, 'FMC Kumo', NULL, 0, NULL, NULL, NULL, NULL, 'storage/hostel_applications/passport_photo/1777991486_PjNkGeT6BL.jpg', 'storage/hostel_applications/applicationform_receipt/1777991486_nPPH4GpUYN.jpg', 'storage/hostel_applications/hostelfee_receipt/1777991486_M8ryHt43nR.jpg', NULL, NULL, 'storage/hostel_applications/admission_letter/1777991486_hpIuXpytIW.jpg', 'Iliyasu Idris', 'Iliyasu Idris', '2026-05-05', 'Babangida Idi', '2026-05-05', NULL, NULL, NULL, '2026-05-05 13:31:27', '2026-05-05 13:31:27'),
(143, 'LH2026050002', 'pending', NULL, NULL, NULL, '2026', '85000', 'Sule Emmanuella Silaneska', '01026034830', 'March, 2026', 'Medicine and surgery', 'Foundation In Science (Health Science)', 'female', '2005-12-04', '09152332889', 'suleemmanuellasilaneska@gmail.com', '243 Recce Battalion Ibereko Armour Barracks Badagry Lagos State', 'Nigerian', 'Kebbi', 'Danko wasagu', 'Sule Esther', 'mother', '08106678349', 'solomonesthersule@gmail.com', 'Ibereko Badagry, Lagos State', 'Civil servant', 'NASRDA', 'Sule Esther', '08106678349', NULL, 'Ibereko Badagry, Lagos State', 'Asthma', 'Chloroquine(drug allergies), smoke, dust and heat.', 'Salbutamol, ventolin and antauds', 'O+', 'AC', NULL, 'non-smoker', 'Covid BCG (tuberculosis) OPV (polio) HBV (hepatitis B) DPT (diphtheria, pertussis, tetanus) Measles Yellow fever Vitamin A', NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, 'storage/hostel_applications/passport_photo/1778053203_pXyYqaTNbk.jpg', 'storage/hostel_applications/applicationform_receipt/1778053203_0t3rheRmRL.jpg', 'storage/hostel_applications/hostelfee_receipt/1778053203_EsBEH0hsdH.jpg', NULL, NULL, 'storage/hostel_applications/admission_letter/1778053203_CsQEAoo3QZ.jpg', 'Sule Emmanuella Silaneska', 'Sule Emmanuella Silaneska', '2026-05-06', 'Sule Esther', '2026-05-06', 'No', 'If I had to put it personally:\r\nI’d choose a hostel for the sense of community—you’re surrounded by people who understand the same academic pressure.\r\nIt reduces decision fatigue (no worrying about rent, bills, or commuting daily).\r\nIt creates a balanced student life, where academics and social life naturally blend.', NULL, '2026-05-06 06:40:03', '2026-05-06 06:40:03'),
(144, 'LH2026050003', 'pending', NULL, NULL, NULL, '2026-2032', '85000', 'Halima Abubakar Jungudo', '01026039062', 'March intake', 'Medicine', 'Faculty of medicine', 'female', '2008-07-07', '09163624455', 'halimaabubakarjungudo2008@gmail.com', 'Orji estate Gombe state', 'Nigerian', 'Gombe state', 'Funakaye', 'Aishatu Muhammad jingi', 'mother', '07067300850', NULL, 'Orji estate Gombe state', 'Nurse', 'Specialist hospital Gombe state', 'Aishatu Muhammad jingi', '07067300850', NULL, 'Orji estate Gombe state', NULL, NULL, NULL, 'A+', 'AA', NULL, 'non-smoker', NULL, NULL, 'FTH KUMO', NULL, 0, NULL, NULL, NULL, NULL, 'storage/hostel_applications/passport_photo/1778700254_dx9lZPfVi8.jpg', 'storage/hostel_applications/applicationform_receipt/1778700254_GnU2hVs6JM.jpg', 'storage/hostel_applications/hostelfee_receipt/1778700254_AgClNk60n3.jpg', NULL, NULL, 'storage/hostel_applications/admission_letter/1778700254_LQPse4ZvGg.png', 'Halima Abubakar Jungudo', 'Halima Abubakar Jungudo', '2026-05-13', 'Aishatu Muhammad jingi', '2026-05-13', 'Yes, I lived in a hostel last year. I enjoyed meeting new people and learning to manage my time and responsibilities independently. It helped me become more disciplined and organized.', 'prefer hostel accommodation because it is close to my classes, provides a safe environment, and gives me the chance to interact with other students and build lasting friendships.', NULL, '2026-05-13 18:24:14', '2026-05-13 18:24:14');
INSERT INTO `hostel_rules` (`id`, `title`, `description`, `category`, `order`, `is_active`, `hostel_id`, `created_at`, `updated_at`) VALUES
(1, 'Room Allocation', 'Students must occupy only the room and bed assigned to them. Unauthorized room changes are strictly prohibited.', 'general', 1, 1, NULL, '2026-01-12 05:58:21', '2026-01-12 05:58:21'),
(2, 'Identity Card', 'Students must carry their hostel ID card at all times within the hostel premises and present it when requested by hostel staff.', 'general', 2, 1, NULL, '2026-01-12 05:58:21', '2026-01-12 05:58:21'),
(3, 'Registration', 'All students must complete the hostel registration process before occupying their rooms.', 'general', 3, 1, NULL, '2026-01-12 05:58:21', '2026-01-12 05:58:21'),
(4, 'Fire Safety', 'Students must familiarize themselves with fire exits and assembly points. Fire drills must be taken seriously. Do not tamper with fire safety equipment.', 'safety', 1, 1, NULL, '2026-01-12 05:58:21', '2026-01-12 05:58:21'),
(5, 'Electrical Safety', 'Do not overload electrical sockets. Report any faulty electrical equipment immediately. Personal high-wattage appliances are not permitted.', 'safety', 2, 1, NULL, '2026-01-12 05:58:21', '2026-04-18 14:09:17'),
(6, 'Emergency Procedures', 'In case of emergency, contact the porter\'s lodge immediately. Emergency contact numbers are displayed on notice boards.', 'safety', 3, 1, NULL, '2026-01-12 05:58:21', '2026-01-12 05:58:21'),
(7, 'Noise Levels', 'Maintain reasonable noise levels at all times. Quiet hours are from 10:00 PM to 7:00 AM. Loud music and disturbances are prohibited.', 'conduct', 1, 1, NULL, '2026-01-12 05:58:21', '2026-01-12 05:58:21'),
(8, 'Respect for Others', 'Treat fellow residents and staff with respect. Harassment, bullying, or discrimination of any kind will not be tolerated.', 'conduct', 2, 1, NULL, '2026-01-12 05:58:21', '2026-01-12 05:58:21'),
(9, 'Dress Code', 'Dress appropriately in common areas. Indecent exposure is prohibited.', 'conduct', 3, 1, NULL, '2026-01-12 05:58:21', '2026-01-12 05:58:21'),
(10, 'Common Areas', 'Keep common areas clean and tidy. Return furniture to its original position after use. Report any damages immediately.', 'facilities', 1, 1, NULL, '2026-01-12 05:58:21', '2026-01-12 05:58:21'),
(11, 'Kitchen Usage', 'Clean up after using the kitchen. Do not leave food unattended while cooking. Dispose of waste properly.', 'facilities', 2, 1, NULL, '2026-01-12 05:58:21', '2026-01-12 05:58:21'),
(12, 'Laundry Facilities', 'Use laundry facilities during designated hours only. Remove clothes promptly after washing.', 'facilities', 3, 1, NULL, '2026-01-12 05:58:21', '2026-01-12 05:58:21'),
(13, 'Visitor Registration', 'All visitors must be registered at the porter\'s lodge. Visitors must present valid identification.', 'visitors', 1, 1, NULL, '2026-01-12 05:58:21', '2026-01-12 05:58:21'),
(14, 'Visiting Hours', 'Visitors are allowed between 8:00 AM and 8:00 PM only. Overnight visitors are strictly prohibited.', 'visitors', 2, 1, NULL, '2026-01-12 05:58:21', '2026-01-12 05:58:21'),
(15, 'Visitor Responsibility', 'Students are responsible for the conduct of their visitors. Visitors must be accompanied at all times.', 'visitors', 3, 1, NULL, '2026-01-12 05:58:21', '2026-01-12 05:58:21'),
(16, 'Curfew Hours', 'All students must be inside the hostel by 10:00 PM on weekdays and 11:00 PM on weekends.', 'curfew', 1, 1, NULL, '2026-01-12 05:58:21', '2026-01-12 05:58:21'),
(17, 'Late Entry', 'Students returning after curfew must sign the late entry register. Repeated violations will result in disciplinary action.', 'curfew', 2, 1, NULL, '2026-01-12 05:58:21', '2026-01-12 05:58:21'),
(18, 'Overnight Leave', 'Students planning to stay out overnight must submit a leave request at least 24 hours in advance.', 'curfew', 3, 1, NULL, '2026-01-12 05:58:21', '2026-01-12 05:58:21'),
(19, 'Room Cleanliness', 'Keep your room clean and tidy at all times. Room inspections may be conducted periodically.', 'cleanliness', 1, 1, NULL, '2026-01-12 05:58:21', '2026-01-12 12:04:43'),
(20, 'Waste Disposal', 'Dispose of waste in designated bins only. Separate recyclable materials where applicable.', 'cleanliness', 2, 1, NULL, '2026-01-12 05:58:21', '2026-01-12 05:58:21'),
(21, 'Bathroom Hygiene', 'Keep bathrooms clean after use. Report any plumbing issues immediately.', 'cleanliness', 3, 1, NULL, '2026-01-12 05:58:21', '2026-01-12 05:58:21'),
(22, 'Alcohol and Drugs', 'Possession, consumption, or distribution of alcohol and illegal drugs is strictly prohibited.', 'prohibited', 1, 1, NULL, '2026-01-12 05:58:21', '2026-01-12 05:58:21'),
(23, 'Weapons', 'Possession of weapons of any kind, including knives and firearms, is strictly prohibited.', 'prohibited', 2, 1, NULL, '2026-01-12 05:58:21', '2026-01-12 05:58:21'),
(24, 'Pets', 'Pets are not allowed in the hostel premises.', 'prohibited', 3, 1, NULL, '2026-01-12 05:58:21', '2026-01-12 05:58:21'),
(25, 'Cooking Appliances', 'Personal cooking appliances such as hot plates, electric kettles, and rice cookers are not allowed in rooms.', 'prohibited', 4, 1, NULL, '2026-01-12 05:58:21', '2026-01-12 05:58:21');
